function statParse(text){
  var nums=[], toks=String(text||'').split(/[\s,;]+/);
  for(var i=0;i<toks.length;i++){
    var t=toks[i].trim(); if(!t) continue;
    var n=Number(t);
    if(t!=='' && !isFinite(n)) return { error:'非法数字：'+t };
    nums.push(n);
  }
  if(nums.length<1) return { error:'至少需要 1 个数字' };
  return { error:null, nums:nums };
}
function statMean(a){ var s=0; for(var i=0;i<a.length;i++) s+=a[i]; return s/a.length; }
function statMedian(a){
  var b=a.slice().sort(function(x,y){ return x-y; });
  var n=b.length, m=Math.floor(n/2);
  return n%2 ? b[m] : (b[m-1]+b[m])/2;
}
function statQuantile(a,p){
  var b=a.slice().sort(function(x,y){ return x-y; });
  if(b.length===1) return b[0];
  var idx=p*(b.length-1), lo=Math.floor(idx), hi=Math.ceil(idx);
  if(lo===hi) return b[lo];
  return b[lo]+(b[hi]-b[lo])*(idx-lo);
}
function statMode(a){
  var f={}, max=0;
  for(var i=0;i<a.length;i++){ var k=a[i]; f[k]=(f[k]||0)+1; if(f[k]>max) max=f[k]; }
  var modes=[]; for(var k in f){ if(f[k]===max) modes.push(Number(k)); }
  return { modes:modes, freq:max };
}
function statVariance(a,sample){
  var m=statMean(a), s=0;
  for(var i=0;i<a.length;i++){ var d=a[i]-m; s+=d*d; }
  return s/((sample===false? a.length : a.length-1)||1);
}
function statStd(a,sample){ return Math.sqrt(statVariance(a,sample)); }
function statSummary(a){
  var q1=statQuantile(a,0.25), q2=statQuantile(a,0.5), q3=statQuantile(a,0.75);
  var mo=statMode(a);
  return {
    n:a.length, min:Math.min.apply(null,a), max:Math.max.apply(null,a),
    sum:a.reduce(function(x,y){ return x+y; },0),
    mean:statMean(a), median:q2, mode:mo.modes, modeFreq:mo.freq,
    variance:statVariance(a,true), std:statStd(a,true),
    q1:q1, q2:q2, q3:q3, iqr:q3-q1
  };
}
function statRegression(pts){
  if(pts.length<2) return { error:'至少需要 2 个点' };
  var n=pts.length, sx=0, sy=0, sxx=0, syy=0, sxy=0;
  for(var i=0;i<n;i++){ var x=pts[i][0], y=pts[i][1]; sx+=x; sy+=y; sxx+=x*x; syy+=y*y; sxy+=x*y; }
  var denom=n*sxx-sx*sx;
  if(denom===0) return { error:'x 方差为零，无法拟合' };
  var slope=(n*sxy-sx*sy)/denom;
  var intercept=(sy-slope*sx)/n;
  var rNum=n*sxy-sx*sy, rDen=Math.sqrt((n*sxx-sx*sx)*(n*syy-sy*sy));
  var r=(rDen===0)?0:rNum/rDen;
  return { slope:slope, intercept:intercept, r:r, r2:r*r };
}
function statHistogram(a,bins){
  bins=bins||Math.min(10,Math.max(2,a.length));
  var mn=Math.min.apply(null,a), mx=Math.max.apply(null,a);
  if(mx===mn) return [{ x0:mn, x1:mn, count:a.length }];
  var w=(mx-mn)/bins, out=[];
  for(var i=0;i<bins;i++) out.push({ x0:mn+i*w, x1:mn+(i+1)*w, count:0 });
  for(var j=0;j<a.length;j++){
    var k=Math.floor((a[j]-mn)/w);
    if(k>=bins) k=bins-1; if(k<0) k=0; out[k].count++;
  }
  return out;
}
function statEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function statHistSvg(a,bins){
  var h=statHistogram(a,bins), maxC=0;
  for(var i=0;i<h.length;i++) if(h[i].count>maxC) maxC=h[i].count;
  var W=680, H=180, PAD=24, bw=(W-PAD*2)/h.length, maxH=H-PAD*2;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  for(var i=0;i<h.length;i++){
    var bh=maxC? maxH*h[i].count/maxC : 0;
    var x=PAD+i*bw, y=H-PAD-bh;
    s+='<rect x="'+(x+2)+'" y="'+y+'" width="'+(bw-4)+'" height="'+bh+'" rx="3" fill="#5E6AD2"/>';
    s+='<text x="'+(x+bw/2)+'" y="'+(H-PAD+14)+'" font-family="system-ui,sans-serif" font-size="10" fill="#71717A" text-anchor="middle">'+statEsc(h[i].count)+'</text>';
  }
  s+='</svg>';
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { statParse:statParse, statMean:statMean, statMedian:statMedian, statQuantile:statQuantile,
    statMode:statMode, statVariance:statVariance, statStd:statStd, statSummary:statSummary,
    statRegression:statRegression, statHistogram:statHistogram, statHistSvg:statHistSvg, statEsc:statEsc };
}
if (typeof window !== 'undefined') {
  window.StatForgePure = { statParse:statParse, statMean:statMean, statMedian:statMedian, statQuantile:statQuantile,
    statMode:statMode, statVariance:statVariance, statStd:statStd, statSummary:statSummary,
    statRegression:statRegression, statHistogram:statHistogram, statHistSvg:statHistSvg, statEsc:statEsc };
}
